// 1. Récupère l'input brut de la requête Mailhog
const input = $input.first().json;
let mailhogData = input.data;

// 2. Si data est une chaîne de caractères (string), on la parse en objet JSON
if (typeof mailhogData === 'string') {
    try {
        mailhogData = JSON.parse(mailhogData);
    } catch (e) {
        mailhogData = {};
    }
} else if (!mailhogData) {
    mailhogData = input;
}

let items = mailhogData.items || [];

// 3. Si aucun e-mail n'est trouvé, on retourne un tableau vide pour stopper le workflow proprement
if (items.length === 0) {
    return [];
}

// 4. On parcourt chaque e-mail pour créer un item n8n indépendant (résout le bug du "dernier mail unique")
return items.map(email => {
    let mailId = email.ID || ""; // On garde l'ID pour la suppression finale (Bug 3)

    // On récupère directement le mail brut complet (en-têtes + corps) depuis Raw.Data (Bug 4)
    let rawEmailData = email.Raw?.Data || "";

    return {
        json: {
            id: mailId,          // Transmet l'ID pour plus tard
            rawEmail: rawEmailData // Transmet le mail complet à ton API FastAPI /analyze
        }
    };
});

const inputData = $input.item.json;
let score = 0;
let reasons = [];

// Les familles de signaux pour croiser les preuves
let hasLookalike = false;      // Famille 1 : Faux domaine (Typosquatting)
let hasReplyToMismatch = false; // Famille 2 : Détournement de réponse
let hasRiskyAttachment = false; // Famille 3 : Pièce jointe dangereuse
let hasPressureWords = false;   // Famille 4 : Urgence / Pression psychologique
let hasAuthFailure = false;     // Famille 5 : Échec SPF/DKIM
let hasKnownMalware = false;    // Ajout : Pièce jointe connue comme malware (VirusTotal)

// 1. Analyse granulaire des règles déclenchées par FastAPI
if (inputData.rules_triggered && Array.isArray(inputData.rules_triggered)) {
    inputData.rules_triggered.forEach(rule => {
        let pts = rule.points || 0;
        score += pts;
        reasons.push(rule.reason);

        // On identifie chaque famille de menace
        if (rule.rule === "lookalike_domain") hasLookalike = true;
        if (rule.rule === "reply_to_mismatch") hasReplyToMismatch = true;
        if (rule.rule === "risky_attachment") hasRiskyAttachment = true;
        if (rule.rule === "pressure_words") hasPressureWords = true;
        if (rule.rule === "known_malware") hasKnownMalware = true;
        if (rule.rule === "auth_fail") hasAuthFailure = true;
    });
}

// (Le bloc redondant de vérification des en-têtes d'authentification a été entièrement supprimé ici)

// 3. Analyse de l'enrichissement (VirusTotal / Âge du domaine)
let maliciousVtCount = 0;
if (inputData.enrichment && inputData.enrichment.domains) {
    for (const [domain, info] of Object.entries(inputData.enrichment.domains)) {
        if (info.age_days !== null && info.age_days < 7) {
            score += 20;
            reasons.push(`Domaine récent (${domain}) créé il y a ${info.age_days} jours (+20)`);
        }
        if (info.vt_malicious && info.vt_malicious >= 3) {
            maliciousVtCount += info.vt_malicious;
            score += 35;
            reasons.push(`VirusTotal signale ${domain} comme malveillant (+35)`);
        }
    }
}

// ==========================================
// INTELLIGENCE ARTIFICIELLE / LOGIQUE MÉTIER
// Corrélation de preuves (Le vrai cerveau SOC)
// ==========================================

let verdict = "BENIGN";
let confidence = "Low";

// Règle de corrélation 1 : Un exécutable louche + un faux domaine de marque = MALICIOUS direct
if (hasRiskyAttachment && hasLookalike) {
    score = Math.max(score, 75);
    reasons.push("[Corrélation SOC] Pièce jointe exécutable combinée à une usurpation de marque.");
}

// Règle de corrélation 2 : Faux domaine + Reply-to externe = Attaque par spear-phishing classique
if (hasLookalike && hasReplyToMismatch) {
    score = Math.max(score, 65);
    reasons.push("[Corrélation SOC] Usurpation de marque couplée à un détournement de réponse (Reply-To).");
}

// Plafonnement du score à 100
score = Math.min(score, 100);

// Attribution du verdict intelligent
let distinctSignalsCount = [hasLookalike, hasReplyToMismatch, hasRiskyAttachment, hasPressureWords, hasAuthFailure, hasKnownMalware].filter(Boolean).length;

if (score >= 60 && distinctSignalsCount >= 2) {
    verdict = "MALICIOUS";
    confidence = "High";
} else if (score >= 30 || (score >= 20 && distinctSignalsCount >= 2)) {
    verdict = "SUSPICIOUS";
    confidence = "Medium";
} else {
    verdict = "BENIGN";
    confidence = "Low"; // Corrigé ici : passe à Low au lieu de High par défaut
}

// --- RÈGLES DE SURCHARGE DE VERDICT (PLANCHERS ET CORRÉLATIONS SOC) ---
if (hasKnownMalware) {
    verdict = "MALICIOUS"; 
    confidence = "High"; 
    score = Math.max(score, 85);
    reasons.push("[Corrélation SOC] Pièce jointe connue comme malware (VirusTotal)");
} else if (hasRiskyAttachment && verdict === "BENIGN") {
    verdict = "SUSPICIOUS"; 
    confidence = "Medium"; 
    score = Math.max(score, 30);
    reasons.push("[Plancher] Exécutable en pièce jointe : jamais BENIGN");
}

// Récupération de l'ID d'origine pour le nettoyage de Mailhog
let mailId = "";
try {
    mailId = $('Code in JavaScript').item.json.id;
} catch (e) {
    mailId = inputData.id || "";
}

return {
    json: {
        id: mailId,
        score: score,
        verdict: verdict,
        confidence: confidence,
        reasons: reasons,
        details: inputData
    }
};;

const data = $input.item.json;
// On extrait les domaines des URLs détectées ou l'adresse email de l'attaquant
let domainsToBlock = [];

if (data.details && data.details.urls) {
    data.details.urls.forEach(url => {
        try {
            let domain = new URL(url).hostname;
            domainsToBlock.push(domain);
        } catch(e) {}
    });
}

// Ajout du domaine de l'expéditeur frauduleux si présent
if (data.details && data.details.from_address) {
    let senderDomain = data.details.from_address.split('@')[1];
    if (senderDomain) domainsToBlock.push(senderDomain);
}

return {
    json: {
        domains: [...new Set(domainsToBlock)] // Supprime les doublons en JS aussi
    }
};

